"743 :     private void calculateStreamMap(final Archive archive) throws IOException {
744 :         final StreamMap streamMap = new StreamMap();
745 :         
746 :         int nextFolderPackStreamIndex = 0;
747 :         final int numFolders = archive.folders != null ? archive.folders.length : 0;
