752 :         }
753 :         
754 :         long nextPackStreamOffset = 0;
755 :         final int numPackSizes = archive.packSizes != null ? archive.packSizes.length : 0;
756 :         streamMap.packStreamOffsets = new long[numPackSizes];
757 :         for (int i = 0; i < numPackSizes; i++) {
758 :             streamMap.packStreamOffsets[i] = nextPackStreamOffset;
759 :             nextPackStreamOffset += archive.packSizes[i]; 
760 :         }
761 :         
762 :         streamMap.folderFirstFileIndex = new int[numFolders];
763 :         streamMap.fileFolderIndex = new int[archive.files.length];
764 :         int nextFolderIndex = 0;
765 :         int nextFolderUnpackStreamIndex = 0;
766 :         for (int i = 0; i < archive.files.length; i++) {
767 :             if (!archive.files[i].hasStream() && nextFolderUnpackStreamIndex == 0) {
768 :                 streamMap.fileFolderIndex[i] = -1;
769 :                 continue;
770 :             }
771 :             if (nextFolderUnpackStreamIndex == 0) {
772 :                 for (; nextFolderIndex < archive.folders.length; ++nextFolderIndex) {
773 :                     streamMap.folderFirstFileIndex[nextFolderIndex] = i;
774 :                     if (archive.folders[nextFolderIndex].numUnpackSubStreams > 0) {
775 :                         break;
776 :                     }
777 :                 }
778 :                 if (nextFolderIndex >= archive.folders.length) {
779 :                     throw new IOException("Too few folders in archive");
